  { id: "pl-krakowskie-przedmiescie", country: "pl", name: "Krakowskie Przedmieście, Warsaw", name_zh: "华沙克拉科夫郊区街", lat: 52.241667, lon: 21.015833, place_type: "original", note: "华沙“王家大道”的第一段，从城堡广场向南，经过大学。普鲁斯把“J. 明采尔与 S. 沃库尔斯基”杂货店安在这条街上；街上有两幢房子挂着纪念牌，标出读者们推算出来的沃库尔斯基和老店员热茨基的“住处”", note_en: "The first stretch of Warsaw's Royal Route, running south from the Castle Square past the university. Prus put the fancy-goods shop of J. Mincel and S. Wokulski here, and plaques on two houses of the street mark where, by readers' reckoning, Wokulski and the old clerk Rzecki 'lived'", coord_checked: "Ulica Krakowskie Przedmieście w Warszawie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Ulica_Krakowskie_Przedmie%C5%9Bcie_w_Warszawie, 2026-11-22", photo: {"file": "images/places/pl-krakowskie-przedmiescie.jpg", "width": 800, "height": 466, "author": "Igor123121", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AKrakowskie_Przedmie%C5%9Bcie_street%2C_2026%2C_Warsaw_Poland_%282%29.jpg", "alt_en": "Krakowskie Przedmieście in Warsaw", "alt_zh": "华沙的克拉科夫郊区街"} },
  { id: "pl-powisle", country: "pl", name: "Powiśle, Warsaw", name_zh: "华沙滨河区", lat: 52.238611, lon: 21.0275, place_type: "original", note: "维斯瓦河边的低地街区，就在大学所在的陡坡之下。《玩偶》里，沃库尔斯基沿卡罗瓦街走下河边，看见穷人的窝棚，以及紧挨着城市水源的垃圾堆", note_en: "The low district along the Vistula, below the escarpment on which the university stands. In The Doll Wokulski walks down Karowa Street to the river and sees the hovels of the poor and the rubbish heaps beside the city's water supply", coord_checked: "Powiśle (Warszawa) (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Powi%C5%9Ble_%28Warszawa%29, 2026-11-22", photo: {"file": "images/places/pl-powisle.jpg", "width": 800, "height": 533, "author": "Dariusz Kowalczyk", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AWis%C5%82a_bulwary_Powi%C5%9Ble_Warszawa_001.jpg", "alt_en": "The Vistula boulevards at Powiśle, with the railway bridge beyond", "alt_zh": "波维希莱的维斯瓦河岸步道，远处是铁路桥"} },
  { id: "pl-lazienki", country: "pl", name: "Łazienki Park, Warsaw", name_zh: "华沙瓦津基公园", lat: 52.214444, lon: 21.031667, place_type: "original", note: "水上宫殿所在的园林，波兰末代国王斯坦尼斯瓦夫·奥古斯特的夏宫。《玩偶》里，伊扎贝拉·文茨卡陪姑母在这里散步，沃库尔斯基守在池塘边，盼着她打个招呼", note_en: "The park of the Palace on the Isle, the summer residence of Stanisław August, the last king of Poland. In The Doll Izabela Łęcka walks here with her aunt, and Wokulski waits by the pond in the hope of a greeting", coord_checked: "Łazienki Królewskie w Warszawie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/%C5%81azienki_Kr%C3%B3lewskie_w_Warszawie, 2026-11-22", photo: {"file": "images/places/pl-lazienki.jpg", "width": 800, "height": 533, "author": "Krzysztof Popławski", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "source": "https://commons.wikimedia.org/wiki/File%3APa%C5%82ac_na_Wyspie%2C_%C5%81azienki_Kr%C3%B3lewskie_w_Warszawie%2C_2025%2C_KsP_004.jpg", "alt_en": "The Palace on the Isle in Łazienki Park", "alt_zh": "瓦津基公园的水上宫殿"} },
  { id: "pl-zamek-krolewski", country: "pl", name: "Royal Castle, Warsaw", name_zh: "华沙王宫城堡", lat: 52.247778, lon: 21.014167, place_type: "original", note: "《科尔迪安》第三幕在城堡前的广场上开场：1829 年沙皇尼古拉一世加冕为波兰国王的那一天；当夜科尔迪安穿过城堡里的一间间屋子去刺杀他，却昏倒在卧室门口。城堡 1944 年被德军炸毁，1971–1984 年重建", note_en: "Act III of Kordian opens on the square before the castle on the day in 1829 when Tsar Nicholas I is crowned King of Poland; that night Kordian goes through the castle rooms to kill him and faints at the bedroom door. The castle was blown up by the Germans in 1944 and rebuilt in 1971–84", coord_checked: "Zamek Królewski w Warszawie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Zamek_Kr%C3%B3lewski_w_Warszawie, 2026-11-22", photo: {"file": "images/places/pl-zamek-krolewski.jpg", "width": 800, "height": 533, "author": "Bahnfrend", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ARoyal_Castle%2C_Warsaw%2C_2006_%2801%29.jpg", "alt_en": "The Royal Castle in Warsaw", "alt_zh": "华沙王宫城堡"} },
  { id: "pl-belweder", country: "pl", name: "Belweder Palace, Warsaw", name_zh: "华沙贝尔维德宫", lat: 52.213056, lon: 21.027222, place_type: "original", note: "乌亚兹多夫大道南端的古典式宫殿，1820 年前后为沙皇的弟弟康斯坦丁大公改建，1918 年以后是国家元首毕苏斯基的官邸。《早春》的结尾，采扎雷·巴雷卡走在一支工人游行队伍的最前面，向它走去", note_en: "The classical palace at the southern end of Ujazdów Avenue, rebuilt around 1820 for the tsar's brother, Grand Duke Constantine, and after 1918 the residence of Józef Piłsudski as head of state. The Spring to Come ends with Cezary Baryka walking at the head of a workers' march towards it", coord_checked: "Belweder w Warszawie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Belweder_w_Warszawie, 2026-11-22", photo: {"file": "images/places/pl-belweder.jpg", "width": 800, "height": 532, "author": "Mkos", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3APa%C5%82ac_Belweder_w_Warszawie.jpg", "alt_en": "Belweder Palace in Warsaw", "alt_zh": "华沙的贝尔维德宫"} },
  { id: "pl-plac-krasinskich", country: "pl", name: "Krasiński Square, Warsaw", name_zh: "华沙克拉辛斯基广场", lat: 52.249167, lon: 21.003611, place_type: "original", note: "这座广场紧挨着华沙犹太隔离区的围墙。1943 年复活节，墙那边的隔离区起义正遭到镇压，这里的旋转木马却照常转着；米沃什那年春天在华沙写下《鲜花广场》，把它同罗马烧死布鲁诺的场面并排放在一起", note_en: "The square lay just outside the wall of the Warsaw ghetto. At Easter 1943, while the ghetto uprising was being put down on the other side, a carousel was turning here; Miłosz's poem 'Campo dei Fiori', written in Warsaw that spring, sets it beside the burning of Giordano Bruno in Rome", coord_checked: "Plac Krasińskich w Warszawie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Plac_Krasi%C5%84skich_w_Warszawie, 2026-11-22", photo: {"file": "images/places/pl-plac-krasinskich.jpg", "width": 800, "height": 278, "author": "Marcin Białek", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3APa%C5%82ac_Krasi%C5%84skich_2011.jpg", "alt_en": "Krasiński Palace seen from the garden side", "alt_zh": "从花园一侧看克拉辛斯基宫"} },
  { id: "pl-stare-miasto", country: "pl", name: "Old Town Market Square, Warsaw", name_zh: "华沙老城集市广场", lat: 52.249722, lon: 21.012222, place_type: "original", note: "1944 年 8 月，起义者守了老城一个月，老城被炸成了瓦砾；现在看到的是战后重建的。比亚沃舍夫斯基当时二十二岁，在老城的地下室里熬过了这几个星期，这也是他那本《回忆录》的核心部分", note_en: "The Old Town was held by the insurgents through August 1944 and bombed and shelled into rubble; what stands now was rebuilt after the war. Białoszewski, who was twenty-two, lived through those weeks in its cellars, and they are at the heart of his Memoir", coord_checked: "Rynek Starego Miasta w Warszawie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Rynek_Starego_Miasta_w_Warszawie, 2026-11-22", photo: {"file": "images/places/pl-stare-miasto.jpg", "width": 800, "height": 535, "author": "Igor123121", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AOld_Town_Market_Square%2C_..2026%2C_Warsaw%2C_Poland.jpg", "alt_en": "The Old Town Market Square in Warsaw", "alt_zh": "华沙老城集市广场"} },
  { id: "pl-umschlagplatz", country: "pl", name: "Umschlagplatz, Warsaw", name_zh: "华沙转运广场", lat: 52.25230833, lon: 20.98907778, place_type: "original", note: "斯塔夫基街铁路岔道旁的装运场；1942 年夏天，华沙隔离区的犹太人就是从这里被送往特雷布林卡的。原址上立着一座 1988 年落成的黑白石纪念碑", note_en: "The loading yard beside the railway siding on Stawki Street from which, in the summer of 1942, the Jews of the Warsaw ghetto were sent to Treblinka. A monument of white and black stone, unveiled in 1988, stands on the spot", coord_checked: "Umschlagplatz (English Wikipedia, article coordinates) — https://en.wikipedia.org/wiki/Umschlagplatz, 2026-11-22", photo: {"file": "images/places/pl-umschlagplatz.jpg", "width": 800, "height": 563, "author": "Adrian Grycuk", "license": "CC BY 3.0 pl", "license_url": "https://creativecommons.org/licenses/by/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3APomnik_Umschlagplatz_2023.jpg", "alt_en": "The Umschlagplatz monument in Warsaw", "alt_zh": "华沙的转运场纪念碑"} },
  { id: "pl-pkin", country: "pl", name: "Palace of Culture and Science, Warsaw", name_zh: "华沙文化科学宫", lat: 52.231667, lon: 21.006389, place_type: "original", note: "苏联人建造的高楼，1955 年完工，是斯大林送给华沙的“礼物”。《小小的启示录》的叙述者是个疲惫的作家，持不同政见的朋友们请他当天晚上在楼前自焚，于是他在城里走了一整天", note_en: "The Soviet-built tower, finished in 1955 as Stalin's 'gift' to Warsaw. The narrator of A Minor Apocalypse, a tired writer, is asked by fellow dissidents to set fire to himself in front of it that evening, and spends the day walking the city", coord_checked: "Pałac Kultury i Nauki (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Pa%C5%82ac_Kultury_i_Nauki, 2026-11-22", photo: {"file": "images/places/pl-pkin.jpg", "width": 800, "height": 580, "author": "Pudelek", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3APalace_of_Culture_and_Science%2C_Warsaw_%28by_Pudelek%29.jpg", "alt_en": "The Palace of Culture and Science in Warsaw", "alt_zh": "华沙科学文化宫"} },
  { id: "pl-krochmalna", country: "pl", name: "Korczak's Orphanage, Krochmalna Street, Warsaw", name_zh: "华沙克罗赫马尔纳街科扎克孤儿院", lat: 52.23425, lon: 20.978401, place_type: "pilgrimage", note: "从 1912 年起，雅努什·科扎克在这幢楼里主持犹太孤儿院“孤儿之家”，当时的门牌是克罗赫马尔纳街 92 号。1940 年孤儿院被迁入隔离区，1942 年 8 月科扎克同他的孩子们一起去了特雷布林卡。克罗赫马尔纳街也是艾萨克·巴什维斯·辛格童年住的街，他的许多小说都回到这条街上", book_ids: ["pl-krol-macius"], note_en: "Janusz Korczak ran the Jewish orphanage Dom Sierot in this building from 1912; its address was then 92 Krochmalna Street. In 1940 the home was moved into the ghetto, and in August 1942 Korczak went with his children to Treblinka. Krochmalna was also the street of Isaac Bashevis Singer's childhood, and much of his fiction comes back to it", coord_checked: "Dom Sierot (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Dom_Sierot, 2026-11-22", photo: {"file": "images/places/pl-krochmalna.jpg", "width": 800, "height": 544, "author": "Adrian Grycuk", "license": "CC BY 3.0 pl", "license_url": "https://creativecommons.org/licenses/by/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3ADom_Sierot_w_Warszawie_2024.jpg", "alt_en": "The former Orphans' Home of Janusz Korczak, now ul. Jaktorowska 6", "alt_zh": "雅努什·科扎克当年的“孤儿之家”，今亚克托罗夫斯卡街 6 号"} },
  { id: "pl-powazki", country: "pl", name: "Powązki Cemetery, Warsaw", name_zh: "华沙波瓦兹基公墓", lat: 52.251944, lon: 20.972778, place_type: "pilgrimage", note: "华沙的老公墓，1790 年启用。葬在这里的作家有普鲁斯、莱蒙特和东布罗夫斯卡等", book_ids: ["pl-lalka", "pl-chlopi", "pl-noce-i-dnie"], note_en: "Warsaw's old cemetery, opened in 1790. Bolesław Prus, Władysław Reymont and Maria Dąbrowska are among the writers buried here", coord_checked: "Cmentarz Powązkowski w Warszawie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Cmentarz_Pow%C4%85zkowski_w_Warszawie, 2026-11-22", photo: {"file": "images/places/pl-powazki.jpg", "width": 800, "height": 534, "author": "Adrian Grycuk", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3ACmentarz_Pow%C4%85zkowski_w_Warszawie_maj_2019.jpg", "alt_en": "An avenue in Powązki Cemetery", "alt_zh": "波翁兹基公墓里的一条林荫道"} },
  { id: "pl-czarnolas", country: "pl", name: "Czarnolas", name_zh: "黑森林村（查尔诺拉斯）", lat: 51.430889, lon: 21.710389, place_type: "original", note: "扬·科哈诺夫斯基的庄园。他 16 世纪 70 年代在这里定居，写下《哀歌》和许多歌与短诗。他的房子和他常在树下写作的那棵椴树都已不存；园中一座 19 世纪的庄园宅邸是他的纪念馆", note_en: "Jan Kochanowski's estate, where he settled in the 1570s and wrote the Laments and many of his songs and epigrams. Neither his house nor the linden he wrote under survives; a nineteenth-century manor in the park holds his museum", coord_checked: "Muzeum Jana Kochanowskiego w Czarnolesie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_Jana_Kochanowskiego_w_Czarnolesie, 2026-11-22", photo: {"file": "images/places/pl-czarnolas.jpg", "width": 800, "height": 600, "author": "Zala", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ACzarnolas_Muzeum_Jana_Kochanowskiego_18.jpg", "alt_en": "The Jan Kochanowski Museum at Czarnolas", "alt_zh": "黑森林村的扬·科哈诺夫斯基博物馆"} },
  { id: "pl-wsola", country: "pl", name: "Gombrowicz Museum, Wsola", name_zh: "弗索拉贡布罗维奇博物馆", lat: 51.486944, lon: 21.122778, place_type: "pilgrimage", note: "这座庄园宅邸原属维托尔德·贡布罗维奇的哥哥耶日，两次大战之间作家常来这里做客，据说《费尔迪杜凯》的构思就产生在这里。现在是维托尔德·贡布罗维奇博物馆", book_ids: ["pl-ferdydurke"], note_en: "The manor that belonged to Witold Gombrowicz's brother Jerzy, where the writer was a frequent guest between the wars; the idea of Ferdydurke is said to have come to him here. It is now the Witold Gombrowicz Museum", coord_checked: "Wsola (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Wsola, 2026-11-22", photo: {"file": "images/places/pl-wsola.jpg", "width": 800, "height": 600, "author": "Rafał Terkner", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AWsola.Pa%C5%82ac_01.JPG", "alt_en": "The manor at Wsola, now the Gombrowicz Museum", "alt_zh": "弗索拉的庄园，今贡布罗维奇博物馆"} },
  { id: "pl-stawisko", country: "pl", name: "Stawisko, Podkowa Leśna", name_zh: "斯塔维斯科", lat: 52.126612, lon: 20.703776, place_type: "pilgrimage", note: "波德科瓦莱希纳林中的宅子，1928 年为雅罗斯瓦夫·伊瓦什凯维奇和妻子安娜而建。他在这里一直住到 1980 年去世，大部分作品都写于此。现为纪念馆", book_ids: ["pl-panny-z-wilka"], note_en: "The house in the woods at Podkowa Leśna built in 1928 for Jarosław Iwaszkiewicz and his wife Anna. He lived here until his death in 1980, and most of his work was written here. It is kept as a museum", coord_checked: "Stawisko (Podkowa Leśna) (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Stawisko_%28Podkowa_Le%C5%9Bna%29, 2026-11-22", photo: {"file": "images/places/pl-stawisko.jpg", "width": 800, "height": 600, "author": "Jolanta Dyr", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3A241112_Villa_in_Stawisko_-_02.jpg", "alt_en": "The villa at Stawisko", "alt_zh": "斯塔维斯科的别墅"} },
  { id: "pl-opinogora", country: "pl", name: "Museum of Romanticism, Opinogóra", name_zh: "奥皮诺古拉浪漫主义博物馆", lat: 52.905612, lon: 20.716314, place_type: "pilgrimage", note: "克拉辛斯基家族庄园里的新哥特式小城堡，《非神曲》作者齐格蒙特·克拉辛斯基的家；他葬在本地堂区教堂的家族墓室里。城堡自 1961 年起是浪漫主义博物馆", book_ids: ["pl-nie-boska"], note_en: "The small neo-Gothic castle on the Krasiński family estate, the home of Zygmunt Krasiński, author of The Un-Divine Comedy; he is buried in the family crypt of the parish church here. The castle has been a Museum of Romanticism since 1961", coord_checked: "Muzeum Romantyzmu w Opinogórze (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_Romantyzmu_w_Opinog%C3%B3rze, 2026-11-22", photo: {"file": "images/places/pl-opinogora.jpg", "width": 800, "height": 536, "author": "Bazie", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AOpinog%C3%B3ra_G%C3%B3rna%2C_Muzeum_Romantyzmu_%281%29.jpg", "alt_en": "A building of the Krasiński estate at Opinogóra, now the Museum of Romanticism", "alt_zh": "奥皮诺古拉克拉辛斯基庄园里的一幢楼，今浪漫主义博物馆"} },
  { id: "pl-treblinka", country: "pl", name: "Treblinka", name_zh: "特雷布林卡", lat: 52.631069, lon: 22.053058, place_type: "original", note: "这座灭绝营从 1942 年 7 月到 1943 年秋天杀害了约八十万犹太人，华沙隔离区的大部分居民都在其中。1944 年格罗斯曼随红军到达这里，根据幸存者和当地人的讲述写下《特雷布林卡地狱》。如今遗址上是一片由数千块石头组成的纪念场", note_en: "The extermination camp where, from July 1942 to the autumn of 1943, some 800,000 Jews were murdered, most of the Warsaw ghetto among them. Vasily Grossman reached the site with the Red Army in 1944 and wrote 'The Hell of Treblinka' from what survivors and local people told him. A field of thousands of stones now marks it", coord_checked: "Obóz zagłady w Treblince (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Ob%C3%B3z_zag%C5%82ady_w_Treblince, 2026-11-22", photo: {"file": "images/places/pl-treblinka.jpg", "width": 800, "height": 530, "author": "Adrian Grycuk", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AStone_Warszawa_Treblinka_Memorial.JPG", "alt_en": "The stone for the Jews of Warsaw among the memorial stones at Treblinka", "alt_zh": "特雷布林卡纪念石阵中纪念华沙犹太人的那一块"} },
  { id: "pl-wawel", country: "pl", name: "Wawel Cathedral, Kraków", name_zh: "克拉科夫瓦维尔主教座堂", lat: 50.054444, lon: 19.935278, place_type: "original", note: "波兰历代国王加冕和安葬的教堂；密茨凯维奇和斯沃瓦茨基葬在这里的“诗圣墓室”。维斯皮扬斯基的《卫城》写的是复活节之夜的这座教堂：陵墓上和挂毯里的人物都活了过来", note_en: "The coronation church and burial place of the Polish kings; Mickiewicz and Słowacki lie in its Crypt of the Bards. Wyspiański's Akropolis takes place in the cathedral on Easter night, when the figures on the tombs and in the tapestries come to life", coord_checked: "Bazylika Archikatedralna św. Stanisława i św. Wacława w Krakowie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Bazylika_Archikatedralna_%C5%9Bw._Stanis%C5%82awa_i_%C5%9Bw._Wac%C5%82awa_w_Krakowie, 2026-11-22", photo: {"file": "images/places/pl-wawel.jpg", "width": 800, "height": 475, "author": "Pudelek", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AWawel_-_cathedral_%28by_Pudelek%29.jpg", "alt_en": "Wawel Cathedral", "alt_zh": "瓦维尔主教座堂"} },
  { id: "pl-mariacki", country: "pl", name: "St Mary's Basilica, Kraków", name_zh: "克拉科夫圣母圣殿", lat: 50.061667, lon: 19.939444, place_type: "original", note: "中央集市广场上的砖砌教堂，两座塔楼一高一矮；高塔上每个整点吹响号角。康拉德少年时在克拉科夫上过学，1914 年夏天重回这里，在《重访波兰》里写了午夜穿过广场的那次散步", note_en: "The brick church with two unequal towers on the Main Market Square; a bugle call is played from the taller one every hour. Conrad, who had lived in Kraków as a schoolboy, came back in the summer of 1914 and described a midnight walk across the square in 'Poland Revisited'", coord_checked: "Kościół Archiprezbiterialny Wniebowzięcia Najświętszej Marii Panny w Krakowie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Ko%C5%9Bci%C3%B3%C5%82_Archiprezbiterialny_Wniebowzi%C4%99cia_Naj%C5%9Bwi%C4%99tszej_Marii_Panny_w_Krakowie, 2026-11-22", photo: {"file": "images/places/pl-mariacki.jpg", "width": 800, "height": 451, "author": "marek7400", "license": "CC BY 3.0", "license_url": "https://creativecommons.org/licenses/by/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AKo%C5%9Bci%C3%B3%C5%82_Mariacki-Rynek-widok_z_Sukiennic_-_panoramio_%282%29.jpg", "alt_en": "St Mary's Basilica seen from the Cloth Hall", "alt_zh": "从纺织会馆望圣玛利亚大教堂"} },
  { id: "pl-bronowice", country: "pl", name: "Rydlówka, Bronowice", name_zh: "布罗诺维采的雷德尔之家", lat: 50.087839, lon: 19.878031, place_type: "original", note: "1900 年 11 月，诗人卢茨扬·雷德尔同农家姑娘雅德维加·米科瓦伊契克的婚宴就在这座乡间宅子里举行。维斯皮扬斯基是宾客之一，第二年 3 月《婚礼》就在克拉科夫上演了。宅子现在是博物馆", note_en: "The manor-cottage where, in November 1900, the wedding party of the poet Lucjan Rydel and the peasant girl Jadwiga Mikołajczykówna was held. Wyspiański was among the guests, and The Wedding was on stage in Kraków the following March. The house is now a museum", coord_checked: "Rydlówka (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Rydl%C3%B3wka, 2026-11-22", photo: {"file": "images/places/pl-bronowice.jpg", "width": 800, "height": 566, "author": "Kgbo", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ARydl%C3%B3wka%2C_Bronowice_Ma%C5%82e%2C_2024%2C_01.jpg", "alt_en": "Rydlówka, the manor house at Bronowice Małe", "alt_zh": "小布罗诺维采的雷德尔故居"} },
  { id: "pl-tyniec", country: "pl", name: "Tyniec Abbey", name_zh: "蒂涅茨修道院", lat: 50.019444, lon: 19.801944, place_type: "original", note: "本笃会修道院，坐落在维斯瓦河边的石灰岩峭壁上，在克拉科夫上游几英里处，创建于 11 世纪。《十字军骑士》就从修道院名下的一家客店写起", note_en: "The Benedictine abbey on a limestone cliff above the Vistula, a few miles upstream from Kraków, founded in the eleventh century. The Knights of the Cross opens in an inn that belongs to it", coord_checked: "Opactwo Benedyktynów w Tyńcu (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Opactwo_Benedyktyn%C3%B3w_w_Ty%C5%84cu, 2026-11-22", photo: {"file": "images/places/pl-tyniec.jpg", "width": 800, "height": 534, "author": "Jakub Hałun", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3A20200529_Widok_ze_Ska%C5%82y_Okr%C4%85%C5%BCek_na_Opactwo_w_Ty%C5%84cu_1735_2128.jpg", "alt_en": "Tyniec Abbey above the Vistula, seen from the Okrążek rock", "alt_zh": "从奥克朗热克岩望维斯瓦河畔的蒂涅茨修道院"} },
  { id: "pl-skalka", country: "pl", name: "Skałka, Kraków", name_zh: "克拉科夫岩上教堂", lat: 50.048333, lon: 19.937778, place_type: "pilgrimage", note: "保禄隐修会的“岩上”教堂。教堂的“功臣墓室”里安葬着维斯皮扬斯基、阿斯尼克、克拉舍夫斯基，2004 年起还有米沃什", book_ids: ["pl-wesele", "pl-w-tatrach", "pl-stara-basn", "pl-ocalenie"], note_en: "The Pauline church 'on the Rock'. Its Crypt of Merit holds the graves of Stanisław Wyspiański, Adam Asnyk, Józef Ignacy Kraszewski and, since 2004, Czesław Miłosz", coord_checked: "Bazylika św. Michała Archanioła i św. Stanisława Biskupa w Krakowie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Bazylika_%C5%9Bw._Micha%C5%82a_Archanio%C5%82a_i_%C5%9Bw._Stanis%C5%82awa_Biskupa_w_Krakowie, 2026-11-22", photo: {"file": "images/places/pl-skalka.jpg", "width": 800, "height": 532, "author": "Jakub Hałun", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3A20200512_Ko%C5%9Bci%C3%B3%C5%82_na_Ska%C5%82ce_w_Krakowie_1822_9951.jpg", "alt_en": "The church on Skałka in Kraków", "alt_zh": "克拉科夫的岩上教堂"} },
  { id: "pl-fabryka-schindlera", country: "pl", name: "Schindler's Factory, Kraków", name_zh: "克拉科夫辛德勒工厂", lat: 50.047347, lon: 19.960658, place_type: "original", note: "利波瓦街 4 号的搪瓷厂，1939 年由奥斯卡·辛德勒接手。他雇用克拉科夫隔离区和普瓦舒夫集中营的犹太人，1944 年又把工人迁往苏台德地区的布吕恩利茨，使一千多人活了下来。办公楼现在是展示占领时期克拉科夫的博物馆", note_en: "The enamelware works at 4 Lipowa Street that Oskar Schindler took over in 1939. By employing Jews from the Kraków ghetto and the Płaszów camp, and by moving his workers to Brünnlitz in the Sudetenland in 1944, he kept more than a thousand people alive. The office building is now a museum of Kraków under the occupation", coord_checked: "Fabryka Emalia Oskara Schindlera (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Fabryka_Emalia_Oskara_Schindlera, 2026-11-22", photo: {"file": "images/places/pl-fabryka-schindlera.jpg", "width": 800, "height": 537, "author": "Adrian Grycuk", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AFabryka_Schindlera_w_Krakowie_2019.jpg", "alt_en": "The former Schindler factory at ul. Lipowa 4", "alt_zh": "利波瓦街 4 号的辛德勒工厂旧址"} },
  { id: "pl-peksowy-brzyzek", country: "pl", name: "Pęksowy Brzyzek Cemetery, Zakopane", name_zh: "扎科帕内佩克索维公墓", lat: 49.296917, lon: 19.947178, place_type: "pilgrimage", note: "扎科帕内木教堂旁的老公墓，葬着把这座山城变成艺术之都的人们，其中有哈乌宾斯基、斯坦尼斯瓦夫·维特凯维奇和马库申斯基。维特凯维奇的儿子、《告别秋天》的作者维特卡西也住在扎科帕内；1939 年 9 月他在今天的乌克兰境内自杀，1988 年迁回这里的遗骨后来证实并不是他的，所以他在这里的墓只是一座象征性的墓", book_ids: ["pl-pozegnanie-jesieni"], note_en: "The old cemetery of Zakopane beside its wooden church, where the people who made the mountain town a capital of the arts are buried, among them Tytus Chałubiński, Stanisław Witkiewicz and Kornel Makuszyński. Witkiewicz's son Witkacy, the author of Farewell to Autumn, who also lived in Zakopane, killed himself in September 1939 in what is now Ukraine; the remains brought here in 1988 turned out not to be his, so his grave is a symbolic one", coord_checked: "Cmentarz Zasłużonych na Pęksowym Brzyzku (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Cmentarz_Zas%C5%82u%C5%BConych_na_P%C4%99ksowym_Brzyzku, 2026-11-22", photo: {"file": "images/places/pl-peksowy-brzyzek.jpg", "width": 800, "height": 600, "author": "AnnMarie", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3ACmentarz_%22Na_P%C4%99ksowym_Brzyzku%22.JPG", "alt_en": "Pęksowy Brzyzek cemetery in Zakopane", "alt_zh": "扎科帕内的彭克索维·布日泽克墓园"} },
  { id: "pl-morskie-oko", country: "pl", name: "Morskie Oko", name_zh: "海眼湖", lat: 49.196944, lon: 20.07, place_type: "original", note: "塔特拉山最大的湖，海拔约 1395 米，卧在门古绍维茨峰群和雷塞峰的峭壁之下。阿斯尼克热爱在塔特拉山中徒步，为它写了一组十四行诗", note_en: "The largest lake of the Tatras, lying at about 1,395 m under the walls of Mięguszowieckie Szczyty and Rysy. Asnyk, a keen walker in the Tatras, wrote a sonnet sequence about it", coord_checked: "Morskie Oko (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Morskie_Oko, 2026-11-22", photo: {"file": "images/places/pl-morskie-oko.jpg", "width": 800, "height": 415, "author": "Hanc Tomasz", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3ATatry%2C_Morskie_Oko_-_panoramio.jpg", "alt_en": "Morskie Oko in the Tatras", "alt_zh": "塔特拉山中的海洋之眼湖"} },
  { id: "pl-czarny-staw", country: "pl", name: "Czarny Staw Gąsienicowy", name_zh: "加雄尼措瓦黑湖", lat: 49.231111, lon: 20.018056, place_type: "original", note: "加雄尼措瓦山谷尽头的冰斗湖，海拔约 1620 米，在扎科帕内上方。泰特马耶尔的《夜雾的旋律》是波兰学生人人读过的诗，副标题里写着这座湖的名字", note_en: "A tarn at about 1,620 m at the head of the Gąsienicowa Valley, above Zakopane. Tetmajer's 'Melody of the Night Mists', which every Polish schoolchild meets, carries its name in the subtitle", coord_checked: "Czarny Staw Gąsienicowy (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Czarny_Staw_G%C4%85sienicowy, 2026-11-22", photo: {"file": "images/places/pl-czarny-staw.jpg", "width": 800, "height": 533, "author": "SkyMaja", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ACzarny_Staw_G%C4%85sienicowy_Tatry_03.JPG", "alt_en": "Czarny Staw Gąsienicowy", "alt_zh": "冈谢尼措瓦黑湖"} },
  { id: "pl-auschwitz", country: "pl", name: "Auschwitz-Birkenau", name_zh: "奥斯威辛-比克瑙", lat: 50.035833, lon: 19.178333, place_type: "original", note: "德国集中营中最大的一座，1940 至 1945 年间有一百多万人在这里被杀害，其中大多数是犹太人。塔德乌什·博罗夫斯基从 1943 年起被关在这里；他战后不久写的那些小说，叙述者是一个靠在比克瑙卸车站台上干活而活下来的囚犯", note_en: "The largest of the German camps, where more than a million people, most of them Jews, were murdered between 1940 and 1945. Tadeusz Borowski was a prisoner here from 1943; the stories he wrote soon after the war are told by a prisoner who survives by working at the unloading ramp of Birkenau", coord_checked: "Auschwitz-Birkenau (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Auschwitz-Birkenau, 2026-11-22", photo: {"file": "images/places/pl-auschwitz.jpg", "width": 800, "height": 532, "author": "Jorge Láscar from Australia", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File%3AInfamous_train_track_to_carry_prisoners_to_gas_chambers_for_execution_-_Auschwitz_II-Birkenau_%289307428048%29.jpg", "alt_en": "The railway track at Auschwitz II-Birkenau", "alt_zh": "奥斯维辛二号营比克瑙的铁轨"} },
  { id: "pl-jasna-gora", country: "pl", name: "Jasna Góra, Częstochowa", name_zh: "琴斯托霍瓦光明山修道院", lat: 50.8125, lon: 19.097222, place_type: "original", note: "保禄隐修会的修道院，供奉着“黑圣母”圣像，是波兰最重要的朝圣地。1655 年底它顶住了瑞典军队的围攻，这是《洪流》的转折点；《塔杜施先生》开篇就向这里的圣母祈祷", note_en: "The Pauline monastery that keeps the icon of the Black Madonna, the chief shrine of Poland. At the end of 1655 it held out against a Swedish siege, which is the turning point of The Deluge; Pan Tadeusz opens with an invocation to its Virgin", coord_checked: "Jasna Góra (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Jasna_G%C3%B3ra, 2026-11-22", photo: {"file": "images/places/pl-jasna-gora.jpg", "width": 800, "height": 530, "author": "Jerzy Szota", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3ACz%C4%99stochowa_klasztor_Jasna_G%C3%B3ra-2162.jpg", "alt_en": "The Pauline monastery of Jasna Góra", "alt_zh": "光明山上的保禄会修道院"} },
  { id: "pl-lubowice", country: "pl", name: "Łubowice (Lubowitz)", name_zh: "武博维采（卢博维茨）", lat: 50.159722, lon: 18.23, place_type: "original", note: "1788 年，约瑟夫·冯·艾兴多夫出生在奥得河上方这里的庄园里，在庄园的花园和树林中长大；这些树林一辈子都回到他的诗里。宅子毁于 1945 年，如今只剩残墙", note_en: "Joseph von Eichendorff was born in the manor here above the Oder in 1788 and grew up in its park and woods, which return in his poems all his life. The house was wrecked in 1945; only ruined walls are left", coord_checked: "Łubowice (województwo śląskie) (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/%C5%81ubowice_%28wojew%C3%B3dztwo_%C5%9Bl%C4%85skie%29, 2026-11-22", photo: {"file": "images/places/pl-lubowice.jpg", "width": 800, "height": 533, "author": "Kamil Czaiński", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3APa%C5%82ac_w_%C5%81ubowicach_-_Schloss_Lubowitz_02.jpg", "alt_en": "The ruins of the Eichendorff family palace at Łubowice", "alt_zh": "武博维采艾兴多夫家宅邸的废墟"} },
  { id: "pl-nikiszowiec", country: "pl", name: "Nikiszowiec, Katowice", name_zh: "卡托维兹尼基绍维茨", lat: 50.243611, lon: 19.082222, place_type: "original", note: "红砖楼房围着内院的矿工住宅区，1908 年起为吉舍矿的工人兴建。《黑色花园》通过住在那里的一个个家庭，讲述尼基绍维茨和邻近的吉绍维茨一百年的历史", note_en: "A miners' estate of red-brick blocks with inner courtyards, built from 1908 for the workers of the Giesche mine. The Black Garden tells a century of Nikiszowiec and its neighbour Giszowiec through the families who lived there", coord_checked: "Nikiszowiec (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Nikiszowiec, 2026-11-22", photo: {"file": "images/places/pl-nikiszowiec.jpg", "width": 800, "height": 532, "author": "Krzysztof Popławski", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AOsiedle_Nikiszowiec%2C_Katowice%2C001%2C_2021-3.jpg", "alt_en": "A miners' tenement at plac Wyzwolenia in Nikiszowiec", "alt_zh": "尼基绍维茨解放广场旁的矿工住宅楼"} },
  { id: "pl-radiostacja", country: "pl", name: "Gliwice Radio Tower", name_zh: "格利维采广播电台", lat: 50.313389, lon: 18.688964, place_type: "original", note: "格莱维茨广播电台的木结构发射塔，高 111 米。1939 年 8 月 31 日晚，党卫军在这里导演了一场“波兰人袭击”，作为入侵波兰的借口。比内克的《第一支波尔卡》写的就是那一天的格莱维茨", note_en: "The wooden transmitter mast of the Gleiwitz radio station, 111 m high. On the evening of 31 August 1939 SS men staged a 'Polish attack' on the station as a pretext for the invasion of Poland. Bienek's The First Polka takes place in Gleiwitz on that day", coord_checked: "Radiostacja gliwicka (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Radiostacja_gliwicka, 2026-11-22", photo: {"file": "images/places/pl-radiostacja.jpg", "width": 800, "height": 800, "author": "Tomasz Górny (Nemo5576)", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AGliwice_Radiostacja_DSC_9386.jpg", "alt_en": "The wooden radio tower at Gliwice", "alt_zh": "格利维采的木制电台发射塔"} },
  { id: "pl-nysa", country: "pl", name: "Eichendorff's grave, Nysa", name_zh: "尼萨的艾兴多夫墓", lat: 50.479842, lon: 17.318925, place_type: "pilgrimage", note: "艾兴多夫晚年住在尼萨（奈塞）女儿家，1857 年 11 月 26 日在那里去世。他同妻子并排葬在耶路撒冷公墓", book_ids: ["pl-eichendorff-gedichte"], note_en: "Eichendorff spent his last years with his daughter's family in Neisse and died there on 26 November 1857. He lies beside his wife in the Jerusalem Cemetery", coord_checked: "Kościół Świętego Krzyża w Nysie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Ko%C5%9Bci%C3%B3%C5%82_%C5%9Awi%C4%99tego_Krzy%C5%BCa_w_Nysie, 2026-11-22", photo: {"file": "images/places/pl-nysa.jpg", "width": 800, "height": 600, "author": "Bonio", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AEichendorff-Grab.JPG", "alt_en": "Joseph von Eichendorff's grave in Nysa", "alt_zh": "约瑟夫·冯·艾兴多夫在尼斯的墓"} },
  { id: "pl-muzeum-pana-tadeusza", country: "pl", name: "Pan Tadeusz Museum, Wrocław", name_zh: "弗罗茨瓦夫《塔杜施先生》博物馆", lat: 51.110417, lon: 17.030583, place_type: "pilgrimage", note: "《塔杜施先生》的手稿 1999 年起归奥索林斯基图书馆所有，这家图书馆 1945 年以后从利沃夫迁到弗罗茨瓦夫。2016 年起，手稿在集市广场一幢房子里的这家博物馆展出", book_ids: ["pl-pan-tadeusz"], note_en: "The manuscript of Pan Tadeusz has belonged since 1999 to the Ossolineum, the library that moved from Lwów to Wrocław after 1945. Since 2016 it has been shown in this museum in a house on the Market Square", coord_checked: "Muzeum „Pana Tadeusza” (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_%E2%80%9EPana_Tadeusza%E2%80%9D, 2026-11-22", photo: {"file": "images/places/pl-muzeum-pana-tadeusza.jpg", "width": 800, "height": 533, "author": "Szczecinolog", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3A6_Market_Square_in_Wroc%C5%82aw%2C_September_2022.jpg", "alt_en": "The house at Rynek 6 in Wrocław, home of the Pan Tadeusz Museum", "alt_zh": "弗罗茨瓦夫集市广场 6 号，《塔杜施先生》博物馆所在的房子"} },
  { id: "pl-wroclaw-glowny", country: "pl", name: "Wrocław Main Station", name_zh: "弗罗茨瓦夫中央火车站", lat: 51.098333, lon: 17.037222, place_type: "original", note: "布雷斯劳带塔楼的中央车站，1857 年启用。《布雷斯劳之死》开头是 1933 年：一节火车车厢里发现了一位男爵的女儿和她女仆的尸体，刑事参事埃伯哈德·莫克接手此案", note_en: "Breslau's turreted main station, opened in 1857. Death in Breslau begins in 1933 with the bodies of a baron's daughter and her maid found in a railway carriage, and Criminal Counsellor Eberhard Mock takes the case", coord_checked: "Wrocław Główny (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Wroc%C5%82aw_G%C5%82%C3%B3wny, 2026-11-22", photo: {"file": "images/places/pl-wroclaw-glowny.jpg", "width": 800, "height": 495, "author": "Jar.ciurus", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AWroclaw_Dworzec_Glowny.jpg", "alt_en": "Wrocław Main Station", "alt_zh": "弗罗茨瓦夫中央车站"} },
  { id: "pl-jagniatkow", country: "pl", name: "Hauptmann House, Jagniątków", name_zh: "亚格尼翁特库夫豪普特曼故居", lat: 50.816849, lon: 15.607869, place_type: "pilgrimage", note: "“草地石之家”，豪普特曼 1900–1901 年在克尔科诺谢山的阿格内滕多夫建造的别墅，此后一直是他的家。1946 年 6 月他在这里去世。现为博物馆", book_ids: ["pl-weber"], note_en: "Haus Wiesenstein, the villa Gerhart Hauptmann had built in 1900–01 at Agnetendorf in the Karkonosze, his home for the rest of his life. He died here in June 1946. It is now a museum", coord_checked: "Muzeum Miejskie „Dom Gerharta Hauptmanna” (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_Miejskie_%E2%80%9EDom_Gerharta_Hauptmanna%E2%80%9D, 2026-11-22", photo: {"file": "images/places/pl-jagniatkow.jpg", "width": 800, "height": 533, "author": "Szymon Staniec", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ADom_Gerharta_Hauptmanna_w_Jagni%C4%85tkowie.jpg", "alt_en": "Gerhart Hauptmann's house at Jagniątków", "alt_zh": "盖哈特·霍普特曼在亚格尼翁特库夫的房子"} },
  { id: "pl-pieszyce", country: "pl", name: "Pieszyce (Peterswaldau)", name_zh: "皮耶希采（彼得斯瓦尔道）", lat: 50.712222, lon: 16.580833, place_type: "original", note: "猫头鹰山下的织工村。1844 年 6 月 4 日，西里西亚织工起义从袭击厂主茨万齐格的宅子开始；第二天蔓延到别拉瓦（朗根比劳），军队向人群开了枪。豪普特曼的《织工》写的就是这几天，茨万齐格在剧中改名德赖西格", note_en: "The weaving village under the Owl Mountains where the rising of the Silesian weavers began on 4 June 1844 with an attack on the house of the manufacturers Zwanziger; next day it spread to Bielawa (Langenbielau), where soldiers fired on the crowd. Hauptmann's The Weavers follows those days, with Zwanziger renamed Dreissiger", coord_checked: "Pieszyce (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Pieszyce, 2026-11-22", photo: {"file": "images/places/pl-pieszyce.jpg", "width": 800, "height": 523, "author": "Jar.ciurus", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3APieszyce_kosciol_sw._Antoniego.jpg", "alt_en": "The former Protestant church in Pieszyce, now St Anthony's", "alt_zh": "佩希采原来的新教教堂，今圣安东尼堂"} },
  { id: "pl-sokolowsko", country: "pl", name: "Sokołowsko (Görbersdorf)", name_zh: "索科沃夫斯科（格贝尔斯多夫）", lat: 50.686944, lon: 16.236389, place_type: "original", note: "石山一条林木山谷里的村庄。19 世纪 50 年代，赫尔曼·布雷默在这里开办了第一家用高山空气治疗肺结核的疗养院，达沃斯是后来学它的。《恩普西翁》的故事发生在 1913 年秋天的这里", note_en: "A village in a wooded valley of the Stone Mountains where Hermann Brehmer opened, in the 1850s, the first sanatorium to treat tuberculosis with mountain air; Davos followed its example. The Empusium is set here in the autumn of 1913", coord_checked: "Sokołowsko (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Soko%C5%82owsko, 2026-11-22", photo: {"file": "images/places/pl-sokolowsko.jpg", "width": 800, "height": 600, "author": "SchiDD", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3ASoko%C5%82owsko%2C_ruiny_sanatorium_Grunwald_%28G%C3%B6rbersdorf_ehem._Sanatorium_Dr._Brehmer_04a%29.jpg", "alt_en": "The ruined Grunwald sanatorium in Sokołowsko", "alt_zh": "索科沃夫斯科的格伦瓦尔德疗养院废墟"} },
  { id: "pl-nowa-ruda", country: "pl", name: "Nowa Ruda", name_zh: "新鲁达", lat: 50.580833, lon: 16.500556, place_type: "original", note: "克沃兹科地区的旧煤矿小城，离捷克边境很近。托卡尔丘克 20 世纪 90 年代起在附近的小村克拉亚努夫有一处房子；《白天的房子，夜晚的房子》由这座小城和山谷里的故事织成，《糜骨之壤》则发生在同一片边境地带的一处高地上", note_en: "A former coal-mining town in the Kłodzko land, close to the Czech border. Tokarczuk has had a house in the nearby hamlet of Krajanów since the 1990s; House of Day, House of Night is made of the stories of the town and its valley, and Drive Your Plow is set on a plateau in the same borderland", coord_checked: "Nowa Ruda (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Nowa_Ruda, 2026-11-22", photo: {"file": "images/places/pl-nowa-ruda.jpg", "width": 800, "height": 471, "author": "Jacek Halicki", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3A2014_Nowa_Ruda%2C_rynek_01.JPG", "alt_en": "The market square and town hall of Nowa Ruda", "alt_zh": "新鲁达的集市广场和市政厅"} },
  { id: "pl-gorzow", country: "pl", name: "Gorzów Wielkopolski (Landsberg an der Warthe)", name_zh: "大波兰地区戈茹夫（瓦尔塔河畔兰茨贝格）", lat: 52.730833, lon: 15.238333, place_type: "original", note: "克里斯塔·沃尔夫 1929 年生在这里，1945 年 1 月随家人向西逃难。《童年典范》围绕她 1971 年夏天回到这座城市的一次短暂访问展开", note_en: "Christa Wolf was born here in 1929 and fled west with her family in January 1945. Patterns of Childhood is built around a short visit she made to the town in the summer of 1971", coord_checked: "Gorzów Wielkopolski (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Gorz%C3%B3w_Wielkopolski, 2026-11-22", photo: {"file": "images/places/pl-gorzow.jpg", "width": 800, "height": 534, "author": "Stiopa", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AMsza_%C5%9Awi%C4%99ta.jpg", "alt_en": "An open-air Mass in front of the cathedral on the Old Market Square, Gorzów", "alt_zh": "戈茹夫老集市广场，主教座堂前的露天弥撒"} },
  { id: "pl-swinoujscie", country: "pl", name: "Świnoujście (Swinemünde)", name_zh: "希维诺乌伊希切（斯维内明德）", lat: 53.907778, lon: 14.2475, place_type: "prototype", prototype_of: "凯辛：艾菲·布里斯特婚后被带去的波罗的海小港。冯塔纳童年在斯维内明德住过五年，他父亲 1827 年起在那里开药房；凯辛就是照着他对这座小城的记忆写的", prototype_of_en: "Kessin, the small Baltic port where Effi Briest is taken as a bride. Fontane spent five years of his childhood in Swinemünde, where his father kept the pharmacy from 1827, and drew Kessin from his memories of it", coord_checked: "Świnoujście (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/%C5%9Awinouj%C5%9Bcie, 2026-11-22", photo: {"file": "images/places/pl-swinoujscie.jpg", "width": 800, "height": 483, "author": "Arro", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3A%C5%9Awinouj%C5%9Bcie%2C_Latarnia_morska_%C5%9Awinouj%C5%9Bcie_-_fotopolska.eu_%28338306%29.jpg", "alt_en": "The lighthouse and harbour cranes at Świnoujście", "alt_zh": "希维诺乌伊希切的灯塔和港口吊车"} },
  { id: "pl-poczta-polska", country: "pl", name: "Polish Post Office, Gdańsk", name_zh: "格但斯克波兰邮局", lat: 54.355261, lon: 18.656856, place_type: "original", note: "1939 年 9 月 1 日，但泽自由市波兰邮局的职员在这幢楼里从清晨到傍晚抵抗德国警察和党卫军；投降的人后来被枪决。“波兰邮局”是《铁皮鼓》里最重要的章节之一。楼里有一部分辟为博物馆", note_en: "On 1 September 1939 the staff of the Polish post office in the Free City of Danzig defended the building from dawn until evening against German police and SS units; those who surrendered were later shot. 'The Polish Post Office' is one of the central chapters of The Tin Drum. Part of the building is a museum", coord_checked: "Muzeum Poczty Polskiej w Gdańsku (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_Poczty_Polskiej_w_Gda%C5%84sku, 2026-11-22", photo: {"file": "images/places/pl-poczta-polska.jpg", "width": 800, "height": 600, "author": "Andrzej Otrębski", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AGdansk_Muzeum_Poczty_Polskiej.jpg", "alt_en": "The Polish Post Office building in Gdańsk, now a museum", "alt_zh": "格但斯克的波兰邮局大楼，今为博物馆"} },
  { id: "pl-wrzeszcz", country: "pl", name: "Wrzeszcz (Langfuhr), Gdańsk", name_zh: "格但斯克弗热什奇（朗富尔）", lat: 54.381944, lon: 18.612778, place_type: "original", note: "君特·格拉斯 1927 年出生的郊区；他在拉贝斯路（今莱莱韦尔街）父母开的杂货店楼上长大，奥斯卡·马策拉特的童年也被安排在这条街上。许勒的《魏泽尔·达维德克》写的是 1957 年夏天的同一片街区", note_en: "The suburb where Günter Grass was born in 1927 and grew up above his parents' grocery in Labesweg, now ul. Lelewela; Oskar Matzerath's childhood is set in the same street. Huelle's Who Was David Weiser? is set in the same district in the summer of 1957", coord_checked: "Wrzeszcz (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Wrzeszcz, 2026-11-22", photo: {"file": "images/places/pl-wrzeszcz.jpg", "width": 800, "height": 600, "author": "Teresa Chrzanowski Flisiuk", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AGda%C5%84sk_ulica_Lelewela.jpg", "alt_en": "Ulica Lelewela in Wrzeszcz, the former Labesweg", "alt_zh": "弗热什奇的莱莱韦尔街，旧名拉贝斯路"} },
  { id: "pl-oliwa", country: "pl", name: "Oliwa, Gdańsk", name_zh: "格但斯克奥利瓦", lat: 54.408056, lon: 18.559167, place_type: "original", note: "古老的西多会修道院及其主教座堂所在的城区，背靠林木覆盖的冰碛丘陵。《哈内曼》写的是 1945 年前后这里的一条别墅街：德国房主离去，从东部来的波兰人家搬进他们的房子", note_en: "The district of the old Cistercian abbey and its cathedral, below wooded moraine hills. Hanemann is set in a villa street here in 1945 and after, as the German owners leave and Polish families from the east move into their houses", coord_checked: "Oliwa (Gdańsk) (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Oliwa_%28Gda%C5%84sk%29, 2026-11-22", photo: {"file": "images/places/pl-oliwa.jpg", "width": 800, "height": 600, "author": "Аимаина хикари", "license": "CC0", "license_url": "http://creativecommons.org/publicdomain/zero/1.0/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AOliwa_Cathedral_7.jpg", "alt_en": "Oliwa Cathedral", "alt_zh": "奥利瓦主教座堂"} },
  { id: "pl-westerplatte", country: "pl", name: "Westerplatte", name_zh: "韦斯特普拉特", lat: 54.408516, lon: 18.675385, place_type: "original", note: "格但斯克港口的半岛。1939 年 9 月 1 日战争打响第一枪之后，约两百人的波兰守军在这里坚守了七天。加乌琴斯基当月写下的那首诗，让阵亡的士兵列队径直走进天堂", note_en: "The peninsula at the mouth of Gdańsk harbour where a Polish garrison of about two hundred men held out for seven days after the first shots of the war on 1 September 1939. Gałczyński's poem, written that same month, sends the fallen soldiers marching straight to heaven", coord_checked: "Westerplatte (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Westerplatte, 2026-11-22", photo: {"file": "images/places/pl-westerplatte.jpg", "width": 800, "height": 533, "author": "Andrzej Otrębski", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AGdansk_Westerplatte_pomnik.jpg", "alt_en": "The Monument to the Defenders of the Coast on Westerplatte", "alt_zh": "西盘半岛上的海岸保卫者纪念碑"} },
  { id: "pl-malbork", country: "pl", name: "Malbork Castle", name_zh: "马尔堡城堡", lat: 54.040064, lon: 19.028394, place_type: "original", note: "诺加特河畔的砖砌要塞，1309 年起是条顿骑士团大团长的驻地，也是欧洲最大的城堡之一。《十字军骑士》里，波兰使者被领着参观城堡，为的是用它的威势吓住他们", note_en: "The brick fortress on the Nogat, from 1309 the seat of the Grand Masters of the Teutonic Order and one of the largest castles in Europe. In The Knights of the Cross Polish envoys are shown round it so that its strength may frighten them", coord_checked: "Zamek w Malborku (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Zamek_w_Malborku, 2026-11-22", photo: {"file": "images/places/pl-malbork.jpg", "width": 800, "height": 600, "author": "Tomasz03", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AZamek_w_Malborku_12.JPG", "alt_en": "Malbork Castle across the Nogat", "alt_zh": "隔着诺加特河望马尔堡城堡"} },
  { id: "pl-grunwald", country: "pl", name: "Grunwald battlefield", name_zh: "格伦瓦尔德古战场", lat: 53.485278, lon: 20.091389, place_type: "original", note: "1410 年 7 月 15 日，国王瓦迪斯瓦夫·雅盖沃率领的波兰-立陶宛联军在这片原野上击败条顿骑士团，大团长乌尔里希·冯·容金根阵亡。这场战役是《十字军骑士》最后的大场面", note_en: "On 15 July 1410 the army of Poland and Lithuania under King Władysław Jagiełło defeated the Teutonic Order on these fields; the Grand Master Ulrich von Jungingen was killed. The battle is the last great scene of The Knights of the Cross", coord_checked: "Grunwald (wieś w województwie warmińsko-mazurskim) (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Grunwald_%28wie%C5%9B_w_wojew%C3%B3dztwie_warmi%C5%84sko-mazurskim%29, 2026-11-22", photo: {"file": "images/places/pl-grunwald.jpg", "width": 800, "height": 531, "author": "Andrzej G", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3AGrunwald%2C_Pole_bitwy_pod_Grunwaldem_-_fotopolska.eu_%28323243%29.jpg", "alt_en": "The fields of Grunwald, with a memorial boulder", "alt_zh": "格伦瓦尔德的田野，前景是一块纪念石"} },
  { id: "pl-frombork", country: "pl", name: "Cathedral Hill, Frombork", name_zh: "弗龙堡主教座堂山", lat: 54.357011, lon: 19.682122, place_type: "pilgrimage", note: "哥白尼是瓦尔米亚教士会的教士，从 1510 年到 1543 年去世，大部分时间住在维斯瓦潟湖边的这座山上；他在这里观测天象，写成《天体运行论》。他葬在主教座堂里", book_ids: ["pl-de-revolutionibus"], note_en: "Copernicus was a canon of the Warmia chapter and lived on this hill above the Vistula Lagoon for most of the years from 1510 until his death in 1543; here he made his observations and wrote On the Revolutions. He is buried in the cathedral", coord_checked: "Wzgórze Katedralne (Frombork) (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Wzg%C3%B3rze_Katedralne_%28Frombork%29, 2026-11-22", photo: {"file": "images/places/pl-frombork.jpg", "width": 800, "height": 533, "author": "Łukasz Niemiec", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AFrombork_-_Wzg%C3%B3rze_Katedralne.jpg", "alt_en": "Cathedral Hill at Frombork", "alt_zh": "弗龙堡的主教座堂山"} },
  { id: "pl-lidzbark", country: "pl", name: "Bishops' Castle, Lidzbark Warmiński", name_zh: "利兹巴克瓦尔米亚主教城堡", lat: 54.125761, lon: 20.582856, place_type: "pilgrimage", note: "瓦尔米亚主教的哥特式城堡。伊格纳齐·克拉西茨基 1767 至 1795 年以采邑主教的身份住在这里，《修士之战》《寓言集》和《讽刺诗》都写于此", book_ids: ["pl-monachomachia"], note_en: "The Gothic castle of the bishops of Warmia. Ignacy Krasicki lived here as prince-bishop from 1767 to 1795, and here he wrote the Monachomachia, the Fables and the Satires", coord_checked: "Zamek Biskupów Warmińskich w Lidzbarku Warmińskim (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Zamek_Biskup%C3%B3w_Warmi%C5%84skich_w_Lidzbarku_Warmi%C5%84skim, 2026-11-22", photo: {"file": "images/places/pl-lidzbark.jpg", "width": 800, "height": 533, "author": "Dawid Galus", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3A646547_Lidzbark_Warmi%C5%84ski_zamek_krzy%C5%BCacki_03.JPG", "alt_en": "The bishops' castle at Lidzbark Warmiński", "alt_zh": "利兹巴克的主教城堡"} },
  { id: "pl-pranie", country: "pl", name: "Pranie Forester's Lodge", name_zh: "普拉涅护林员小屋", lat: 53.611111, lon: 21.5, place_type: "pilgrimage", note: "马祖里地区尼兹凯湖畔的护林员小屋，加乌琴斯基在生命的最后几年（1950–1953）来这里度夏，《奥尔什丁纪事》等晚期诗作就写于此。现为他的纪念馆", book_ids: ["pl-kronika-olsztynska"], note_en: "The forester's lodge on Lake Nidzkie in Masuria where Konstanty Ildefons Gałczyński spent the summers of his last years, 1950–53; the Olsztyn Chronicle and other late poems were written here. It is now his museum", coord_checked: "Muzeum Konstantego Ildefonsa Gałczyńskiego w Praniu (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_Konstantego_Ildefonsa_Ga%C5%82czy%C5%84skiego_w_Praniu, 2026-11-22", photo: {"file": "images/places/pl-pranie.jpg", "width": 800, "height": 570, "author": "Andrzej Wolinski", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3ALe%C5%9Bnicz%C3%B3wka_%22Pranie%22_-_panoramio.jpg", "alt_en": "The forester's lodge at Pranie", "alt_zh": "普拉涅的护林人小屋"} },
  { id: "pl-bialowieza", country: "pl", name: "Białowieża Forest", name_zh: "比亚沃维耶扎原始森林", lat: 52.766667, lon: 23.866667, place_type: "original", note: "欧洲保存最完好的低地原始森林，位于波兰同白俄罗斯的边境上，也是欧洲野牛的家园。《塔杜施先生》第四卷开头就是对这里的树木说话", note_en: "The best-preserved primeval lowland forest in Europe, on the border with Belarus, and the home of the European bison. Book IV of Pan Tadeusz opens by addressing its trees", coord_checked: "Białowieski Park Narodowy (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Bia%C5%82owieski_Park_Narodowy, 2026-11-22", photo: {"file": "images/places/pl-bialowieza.jpg", "width": 800, "height": 533, "author": "FrDr", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ABia%C5%82owieski_Park_Narodowy_0200_28.jpg", "alt_en": "Fallen and standing dead wood in Białowieża National Park", "alt_zh": "比亚沃维耶扎国家公园里的倒木和枯立木"} },
  { id: "pl-goplo", country: "pl", name: "Mouse Tower, Kruszwica", name_zh: "克鲁什维察鼠塔", lat: 52.672136, lon: 18.327203, place_type: "original", note: "戈普沃湖畔的这座砖塔是一座 14 世纪城堡的遗存；传说恶王波皮耶尔就是在这里被老鼠吃掉的。克拉舍夫斯基的《古老的传说》在这片湖岸上讲了波皮耶尔的覆灭，斯沃瓦茨基也把《巴拉迪娜》安排在“戈普沃湖附近”", note_en: "The brick tower on Lake Gopło is what is left of a fourteenth-century castle; legend puts here the wicked prince Popiel, who was eaten by mice. Kraszewski's An Ancient Tale tells the fall of Popiel on this shore, and Słowacki set Balladyna 'near Lake Gopło'", coord_checked: "Mysia Wieża (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Mysia_Wie%C5%BCa, 2026-11-22", photo: {"file": "images/places/pl-goplo.jpg", "width": 800, "height": 600, "author": "Gornypatryk", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AMysia_Wie%C5%BCa_%28Mouse_Tower%29.jpg", "alt_en": "The Mouse Tower at Kruszwica", "alt_zh": "克鲁什维察的鼠塔"} },
  { id: "pl-torun-kopernik", country: "pl", name: "Copernicus House, Toruń", name_zh: "托伦哥白尼故居", lat: 53.009222, lon: 18.603944, place_type: "pilgrimage", note: "老城里的哥特式商人住宅，相传是哥白尼的出生地；他 1473 年 2 月 19 日生于托伦。现为博物馆", book_ids: ["pl-de-revolutionibus"], note_en: "The Gothic merchant's house in the old town held to be the birthplace of Nicolaus Copernicus, born in Toruń on 19 February 1473. It is a museum", coord_checked: "Dom Kopernika w Toruniu (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Dom_Kopernika_w_Toruniu, 2026-11-22", photo: {"file": "images/places/pl-torun-kopernik.jpg", "width": 800, "height": 600, "author": "Pproblem", "license": "CC BY 3.0", "license_url": "https://creativecommons.org/licenses/by/3.0", "source": "https://commons.wikimedia.org/wiki/File%3ADom_kopernika.jpg", "alt_en": "The Gothic gables of the Copernicus House in Toruń", "alt_zh": "托伦哥白尼故居的哥特式山墙"} },
  { id: "pl-kalisz", country: "pl", name: "Kalisz", name_zh: "卡利什", lat: 51.760833, lon: 18.086944, place_type: "original", note: "玛丽亚·东布罗夫斯卡 1889 年出生在几英里外的鲁苏夫，在卡利什上过学。这座城就是《黑夜与白昼》里的卡利涅茨；小说结束在 1914 年 8 月，德军炮轰并烧毁了这座城", note_en: "Maria Dąbrowska was born at Russów, a few miles away, in 1889 and went to school in Kalisz. It is the Kaliniec of Nights and Days, and the novel ends in August 1914, when German troops shelled and burned the town", coord_checked: "Kalisz (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Kalisz, 2026-11-22", photo: {"file": "images/places/pl-kalisz.jpg", "width": 800, "height": 600, "author": "Peżot", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AKalisz_ratusz_2024.jpg", "alt_en": "The town hall on the main square of Kalisz", "alt_zh": "卡利什主广场上的市政厅"} },
  { id: "pl-jezyce", country: "pl", name: "Jeżyce, Poznań", name_zh: "波兹南耶日采区", lat: 52.412778, lon: 16.903333, place_type: "original", note: "市中心以西的街区，满是世纪之交的公寓楼。穆谢罗维奇那套写博雷伊科一家和邻居们的长篇系列小说，就发生在罗斯福街 5 号和周围的街道上，读者管它叫“耶日采记”", note_en: "A district of turn-of-the-century tenements west of the city centre. Musierowicz's long series of novels about the Borejko family and their neighbours is set at 5 Roosevelt Street and in the streets around, and readers call it the Jeżycjada", coord_checked: "Jeżyce (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Je%C5%BCyce, 2026-11-22", photo: {"file": "images/places/pl-jezyce.jpg", "width": 800, "height": 600, "author": "XMICHCIOx", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3APozna%C5%84_ul._F.D._Roosevelta_3%2C_kamienica.jpg", "alt_en": "An Art Nouveau tenement at ul. Roosevelta 3, Jeżyce", "alt_zh": "耶日采罗斯福街 3 号的新艺术风格公寓楼"} },
  { id: "pl-smielow", country: "pl", name: "Mickiewicz Museum, Śmiełów", name_zh: "希米耶武夫密茨凯维奇博物馆", lat: 52.10645, lon: 17.5712, place_type: "pilgrimage", note: "一座古典式乡间宅邸。1831 年夏末密茨凯维奇住在这里，想越境进入俄占区参加十一月起义，但没等他过去起义就失败了。一般认为，这座宅子和这里的人在他不久后于巴黎写成的《塔杜施先生》里留下了痕迹", book_ids: ["pl-pan-tadeusz"], note_en: "The classical country house where Mickiewicz stayed in the late summer of 1831, hoping to cross into the Russian partition and join the November Uprising, which fell before he could. The house and its people are thought to have left their mark on Pan Tadeusz, written in Paris soon after", coord_checked: "Pałac w Śmiełowie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Pa%C5%82ac_w_%C5%9Amie%C5%82owie, 2026-11-22", photo: {"file": "images/places/pl-smielow.jpg", "width": 800, "height": 600, "author": "Maurycek", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3APa%C5%82ac_w_%C5%9Amie%C5%82owie_%282%29.jpg", "alt_en": "The palace at Śmiełów", "alt_zh": "希米耶武夫的宫殿"} },
  { id: "pl-piotrkowska", country: "pl", name: "Piotrkowska Street, Łódź", name_zh: "罗兹彼得科夫斯卡大街", lat: 51.776111, lon: 19.454722, place_type: "original", note: "罗兹的主街，长四公里多，两旁是棉纺业繁荣年代留下的公寓楼、银行和宫殿。《福地》开头是一个下雨的清晨，工人们沿着这条街匆匆赶去上工", note_en: "The main street of Łódź, more than four kilometres long, lined with the tenements, banks and palaces of the cotton boom. The Promised Land begins on a wet morning as the factory hands hurry along it to work", coord_checked: "Ulica Piotrkowska w Łodzi (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Ulica_Piotrkowska_w_%C5%81odzi, 2026-11-22", photo: {"file": "images/places/pl-piotrkowska.jpg", "width": 800, "height": 600, "author": "WrS.tm.pl", "license": "Public domain", "license_url": "https://creativecommons.org/publicdomain/mark/1.0/", "source": "https://commons.wikimedia.org/wiki/File%3APiotrkowska_Street_in_%C5%81%C3%B3d%C5%BA_at_the_intersection_with_Tuwima_Street._July_2023%2C_%C5%81%C3%B3dz%2C_Poland.jpg", "alt_en": "Piotrkowska Street in Łódź", "alt_zh": "罗兹的彼得科夫斯卡街"} },
  { id: "pl-palac-poznanskiego", country: "pl", name: "Poznański Palace, Łódź", name_zh: "罗兹波兹南斯基宫", lat: 51.779111, lon: 19.450822, place_type: "original", note: "棉纺厂主伊兹拉埃尔·波兹南斯基的宫殿，就建在他的工厂旁边；工厂如今改成了“曼努法克图拉”商业文化区。《福地》里那些工厂大王就是照着他这样的人写的。宫殿现为罗兹城市博物馆", note_en: "The palace of the cotton manufacturer Izrael Poznański, built beside his mill, which is now the Manufaktura complex. Men like him are the models for the factory kings of The Promised Land. The palace houses the Museum of the City of Łódź", coord_checked: "Pałac Izraela Poznańskiego (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Pa%C5%82ac_Izraela_Pozna%C5%84skiego, 2026-11-22", photo: {"file": "images/places/pl-palac-poznanskiego.jpg", "width": 800, "height": 600, "author": "kreon1974", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3A%C5%81%C3%B3d%C5%BA-Pa%C5%82ac_Pozna%C5%84skiego_-_panoramio.jpg", "alt_en": "The Poznański Palace in Łódź", "alt_zh": "罗兹的波兹南斯基宫"} },
  { id: "pl-lipce", country: "pl", name: "Lipce Reymontowskie", name_zh: "利普采-莱蒙托夫斯凯", lat: 51.900278, lon: 19.942222, place_type: "original", note: "1890 年前后，莱蒙特在这个村子附近的华沙—维也纳铁路上工作，后来把村名给了《农民》里的利普采；小说跟着一个村庄走过一年四季。1983 年，村子在自己的名字后面加上了他的名字", note_en: "Reymont worked on the Warsaw–Vienna railway near this village around 1890 and gave its name to the Lipce of The Peasants, which follows one village through the four seasons of a year. In 1983 the village added his name to its own", coord_checked: "Lipce Reymontowskie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Lipce_Reymontowskie, 2026-11-22", photo: {"file": "images/places/pl-lipce.jpg", "width": 800, "height": 600, "author": "Radosław Botev", "license": "CC BY 3.0 pl", "license_url": "https://creativecommons.org/licenses/by/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AMuzeum_Regionalne_im._W%C5%82._St._Reymonta_%E2%80%93_Lipce_Reymontowskie_%281%29.jpg", "alt_en": "The yard of the Reymont Regional Museum in Lipce Reymontowskie", "alt_zh": "利普采的莱蒙特地方博物馆院子"} },
  { id: "pl-radegast", country: "pl", name: "Radegast Station, Łódź", name_zh: "罗兹拉德加斯特车站", lat: 51.80214, lon: 19.480133, place_type: "original", note: "罗兹隔离区的装运车站；1942–1944 年，隔离区的人就是从这里被送往海乌姆诺和奥斯威辛的灭绝营。尤雷克·贝克尔生于罗兹（大概是 1937 年），幼年在这个隔离区度过；《说谎者雅各布》里的隔离区没有名字，却是照着它写的", note_en: "The loading station of the Łódź ghetto, from which its people were sent to the death camps at Chełmno and Auschwitz in 1942–44. Jurek Becker, born in Łódź, probably in 1937, spent his early childhood in that ghetto; the ghetto of Jacob the Liar has no name, but it is drawn from it", coord_checked: "Radegast train station (English Wikipedia, article coordinates) — https://en.wikipedia.org/wiki/Radegast_train_station, 2026-11-22", photo: {"file": "images/places/pl-radegast.jpg", "width": 800, "height": 600, "author": "daniel.s", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File%3A%C5%81%C3%B3d%C5%BA_Stacja_Radegast.JPG", "alt_en": "The wooden station building at Radegast in the snow", "alt_zh": "雪中的拉德加斯特车站木屋"} },
  { id: "pl-kielce", country: "pl", name: "Żeromski's School, Kielce", name_zh: "凯尔采热罗姆斯基母校", lat: 50.867911, lon: 20.629472, place_type: "original", note: "凯尔采旧日的男子中学，热罗姆斯基 1874 至 1886 年在这里读书。它就是《西西弗斯的劳役》里克莱里科夫的那所学校：波兰孩子在这里用俄语上课，还被教着瞧不起自己的语言。现在是作家学生时代纪念馆", note_en: "The former boys' gymnasium of Kielce, where Stefan Żeromski was a pupil from 1874 to 1886. It is the school of Kleryków in The Labours of Sisyphus, where Polish boys are taught in Russian and taught to despise their own language. It is now a museum of the writer's school years", coord_checked: "Muzeum Stefana Żeromskiego (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_Stefana_%C5%BBeromskiego, 2026-11-22", photo: {"file": "images/places/pl-kielce.jpg", "width": 800, "height": 600, "author": "Zala", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AKielce_Muzeum_Stefana_%C5%BBeromskiego_06.jpg", "alt_en": "A room in the Museum of Stefan Żeromski's School Years, Kielce", "alt_zh": "凯尔采“热罗姆斯基学生时代博物馆”的一间展室"} },
  { id: "pl-swiety-krzyz", country: "pl", name: "Łysa Góra (Święty Krzyż)", name_zh: "韦萨山（圣十字山）", lat: 50.860278, lon: 21.046944, place_type: "original", note: "圣十字山脉的第二高峰，又名韦希耶茨山，山上古老的本笃会修道院隐在冷杉和山毛榉林中。热罗姆斯基在山下的切科蒂村长大；《冷杉林》是他最后的作品之一，是献给这片山林的颂歌", note_en: "The second summit of the Świętokrzyskie Mountains, also called Łysiec, with its old Benedictine abbey among fir and beech forest. Żeromski grew up below these hills at Ciekoty; The Fir Forest, one of his last works, is a hymn to them", coord_checked: "Łysa Góra (Góry Świętokrzyskie) (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/%C5%81ysa_G%C3%B3ra_%28G%C3%B3ry_%C5%9Awi%C4%99tokrzyskie%29, 2026-11-22", photo: {"file": "images/places/pl-swiety-krzyz.jpg", "width": 800, "height": 600, "author": "Agnieszka Kwiecień, Nova", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AGo%C5%82oborze_%C5%81ysa_G%C3%B3ra_G%C3%B3ry_%C5%9Awi%C4%99tokrzyskie_2020-08-15_10.jpg", "alt_en": "The boulder field on the slope of Łysa Góra", "alt_zh": "秃山山坡上的乱石滩"} },
  { id: "pl-oblegorek", country: "pl", name: "Sienkiewicz Manor, Oblęgorek", name_zh: "奥布文戈雷克显克维奇庄园", lat: 50.95747, lon: 20.475688, place_type: "pilgrimage", note: "这座庄园由公众募捐买下，1900 年赠给显克维奇，纪念他写作二十五周年；《十字军骑士》的单行本也在这一年出版。到 1914 年为止，他一直把这里当作夏季住所。1958 年起为博物馆", book_ids: ["pl-krzyzacy", "pl-potop"], note_en: "The manor bought by public subscription and given to Sienkiewicz in 1900 to mark twenty-five years of his writing life, the year The Knights of the Cross came out as a book. He used it as a summer house until 1914. It has been a museum since 1958", coord_checked: "Muzeum Henryka Sienkiewicza w Oblęgorku (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_Henryka_Sienkiewicza_w_Obl%C4%99gorku, 2026-11-22", photo: {"file": "images/places/pl-oblegorek.jpg", "width": 800, "height": 574, "author": "Gorofil", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3AObl%C4%99gorek._Pa%C5%82acyk_z_Muzeum_Henryka_Sienkiewicza_4.jpg", "alt_en": "Sienkiewicz's manor at Oblęgorek", "alt_zh": "显克维奇在奥布文戈雷克的庄园"} },
  { id: "pl-sandomierz", country: "pl", name: "Sandomierz", name_zh: "桑多梅日", lat: 50.679722, lon: 21.749167, place_type: "original", note: "维斯瓦河边高坡上的古城。维斯瓦夫·梅希里夫斯基 1932 年出生在城外的德维科齐，在这里上过学；《地平线》里男孩和父母战后住的那座山城，就是照着它写的", note_en: "The old town on a bluff above the Vistula. Wiesław Myśliwski was born at Dwikozy, just outside it, in 1932 and went to school here; the hill town of Horizon, where the boy and his parents live after the war, is drawn from it", coord_checked: "Sandomierz (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Sandomierz, 2026-11-22", photo: {"file": "images/places/pl-sandomierz.jpg", "width": 800, "height": 450, "author": "Piotr Tomaszewski", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AStare_miasto_w_Sandomierzu_z_lotu_ptaka.jpg", "alt_en": "The old town of Sandomierz from the air", "alt_zh": "空中俯瞰桑多梅日老城"} },
  { id: "pl-lublin", country: "pl", name: "Old Town, Lublin", name_zh: "卢布林老城", lat: 51.248889, lon: 22.568889, place_type: "original", note: "有城墙的老城，下方是昔日的犹太区“城堡下”。《卢布林的魔术师》从 19 世纪最后几十年的这里写起。切霍维奇 1903 年生于卢布林，1939 年 9 月在这座城里死于德军的炸弹；他的《卢布林城之诗》是一次穿过城中街巷的夜行", note_en: "The walled old town above the former Jewish quarter of Podzamcze. The Magician of Lublin begins here in the last decades of the nineteenth century. Czechowicz, born in Lublin in 1903 and killed in it by a German bomb in September 1939, made his Poem about the City of Lublin a night walk through its streets", coord_checked: "Stare Miasto (Lublin) (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Stare_Miasto_%28Lublin%29, 2026-11-22", photo: {"file": "images/places/pl-lublin.jpg", "width": 800, "height": 672, "author": "kuba13", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3ALublin%2C_Brama_Krakowska_-_fotopolska.eu_%28336746%29.jpg", "alt_en": "The Kraków Gate in Lublin", "alt_zh": "卢布林的克拉科夫门"} },
  { id: "pl-kazimierz-dolny", country: "pl", name: "Kazimierz Dolny", name_zh: "下卡齐米日", lat: 51.322222, lon: 21.9475, place_type: "original", note: "维斯瓦河畔的文艺复兴式粮商小城，两次大战之间是画家聚居地。玛丽亚·孔采维奇娃把《两个月亮》里那些互相勾连的短篇安排在这里；她和丈夫 20 世纪 30 年代盖的房子现在是纪念馆", note_en: "The Renaissance grain-trading town on the Vistula, a painters' colony between the wars. Maria Kuncewiczowa set the linked stories of Two Moons here, and the house she and her husband built in the 1930s is now a museum", coord_checked: "Kazimierz Dolny (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Kazimierz_Dolny, 2026-11-22", photo: {"file": "images/places/pl-kazimierz-dolny.jpg", "width": 800, "height": 662, "author": "Jasny63", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AKazimierz_Dolny%2C_Rynek_18.JPG", "alt_en": "The Gdańska house on the market square of Kazimierz Dolny", "alt_zh": "卡齐米日-多尔尼集市广场上的“格但斯克”楼"} },
  { id: "pl-naleczow", country: "pl", name: "Żeromski's Cottage, Nałęczów", name_zh: "纳文丘夫热罗姆斯基小屋", lat: 51.289444, lon: 22.210556, place_type: "pilgrimage", note: "热罗姆斯基 1905 年在疗养地纳文丘夫盖的扎科帕内式小屋，用作写作的地方；1890 年前后他在这里当过家庭教师，并结识了第一任妻子。《无家可归的人们》里的疗养地“齐塞”就是以纳文丘夫为原型的。小屋 1928 年起为纪念馆", book_ids: ["pl-ludzie-bezdomni"], note_en: "The cottage in the Zakopane style that Żeromski had built in 1905 as a place to write in the spa of Nałęczów, where he had worked as a tutor around 1890 and met his first wife. The spa of Cisy in Homeless People is modelled on Nałęczów. The cottage has been a museum since 1928", coord_checked: "Muzeum Stefana Żeromskiego w Nałęczowie (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_Stefana_%C5%BBeromskiego_w_Na%C5%82%C4%99czowie, 2026-11-22", photo: {"file": "images/places/pl-naleczow.jpg", "width": 800, "height": 706, "author": "Nutaj", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3APL_Na%C5%82%C4%99cz%C3%B3w_chata_%C5%BBeromskiego.jpg", "alt_en": "Żeromski's wooden cottage in Nałęczów", "alt_zh": "热罗姆斯基在纳文丘夫的木屋"} },
  { id: "pl-goraj", country: "pl", name: "Goraj", name_zh: "戈拉伊", lat: 50.721389, lon: 22.667222, place_type: "original", note: "卢布林以南丘陵里的小镇。辛格的外祖父曾是附近比乌戈拉伊的拉比，他自己青年时代也在那里住过；他把第一部长篇安排在 1665–1666 年的戈拉伊：假弥赛亚沙巴泰·泽维的消息传到了一个刚从 1648 年哥萨克屠杀中缓过气来的社区", note_en: "A small town in the hills south of Lublin. Singer, who spent part of his youth in nearby Biłgoraj, where his grandfather had been rabbi, set his first novel here in 1665–66, when news of the false messiah Sabbatai Zevi reaches a community that has barely recovered from the Cossack massacres of 1648", coord_checked: "Goraj (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Goraj, 2026-11-22", photo: {"file": "images/places/pl-goraj.jpg", "width": 800, "height": 600, "author": "Bartek z Polski", "license": "CC0", "license_url": "http://creativecommons.org/publicdomain/zero/1.0/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AGoraj%2C_rynek_02.jpg", "alt_en": "The small park on the market square of Goraj", "alt_zh": "戈拉伊集市广场上的小公园"} },
  { id: "pl-odrzykon", country: "pl", name: "Kamieniec Castle, Odrzykoń", name_zh: "奥德日孔卡缅涅茨城堡", lat: 49.742522, lon: 21.786178, place_type: "prototype", prototype_of: "《复仇》里的城堡。17 世纪时，克罗斯诺附近山顶上的这座城堡分属两家互相争吵的邻居；弗雷德罗的妻子带来的嫁妆里有半座城堡，他从中发现了两家为一堵墙打官司的法庭记录，写成了这部喜剧", prototype_of_en: "The castle of Revenge. In the seventeenth century this hilltop castle near Krosno was owned in two halves by quarrelling neighbours; Fredro, whose wife brought half of it as her dowry, found the court records of their dispute over a wall and made the comedy out of them", coord_checked: "Zamek Kamieniec (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Zamek_Kamieniec, 2026-11-22", photo: {"file": "images/places/pl-odrzykon.jpg", "width": 800, "height": 530, "author": "Scots", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3AZamek_Kamieniec_-_Odrzyko%C5%84.jpg", "alt_en": "The ruins of Kamieniec Castle above Odrzykoń", "alt_zh": "奥杰孔村上方的卡缅涅茨城堡废墟"} },
  { id: "pl-zarnowiec", country: "pl", name: "Konopnicka Manor, Żarnowiec", name_zh: "扎尔诺维茨科诺普尼茨卡庄园", lat: 49.68798, lon: 21.66856, place_type: "pilgrimage", note: "1903 年，为纪念玛丽亚·科诺普尼茨卡写作二十五周年，国人把这座庄园赠给了她。到 1910 年为止，她每年天暖的时候都住在这里，并在这里写完了《巴尔采尔先生在巴西》。现为她的纪念馆", book_ids: ["pl-pan-balcer"], note_en: "The manor given to Maria Konopnicka by the nation in 1903 to mark twenty-five years of her writing. She spent the warmer months here until 1910 and finished Mr Balcer in Brazil in it. It is now her museum", coord_checked: "Muzeum Marii Konopnickiej w Żarnowcu (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Muzeum_Marii_Konopnickiej_w_%C5%BBarnowcu, 2026-11-22", photo: {"file": "images/places/pl-zarnowiec.jpg", "width": 800, "height": 523, "author": "Przykuta", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File%3A%C5%BBarnowiec_dworek_Konopnickiej_2015.08.27_p.jpg", "alt_en": "Maria Konopnicka's manor at Żarnowiec", "alt_zh": "玛丽亚·科诺普尼茨卡在扎尔诺维茨的庄园"} },
  { id: "pl-dukla", country: "pl", name: "Dukla", name_zh: "杜克拉", lat: 49.555, lon: 21.684444, place_type: "original", note: "低贝斯基德山杜克拉山口下的小城，有一座集市广场、一座巴洛克宫殿和两座教堂。斯塔休克住在同一片山里的一个村子，在以它为名的那本书里一次次回到这里", note_en: "A small town below the Dukla Pass in the Low Beskids, with a market square, a baroque palace and two churches. Stasiuk, who lives in a village of the same hills, keeps coming back to it in the book that bears its name", coord_checked: "Dukla (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Dukla, 2026-11-22", photo: {"file": "images/places/pl-dukla.jpg", "width": 800, "height": 530, "author": "Scots", "license": "CC BY-SA 3.0 pl", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/pl/deed.en", "source": "https://commons.wikimedia.org/wiki/File%3ADukla_-_pa%C5%82ac.jpg", "alt_en": "The palace at Dukla", "alt_zh": "杜克拉的宫殿"} },
  { id: "pl-sanok", country: "pl", name: "Sanok", name_zh: "萨诺克", lat: 49.56, lon: 22.202222, place_type: "original", note: "桑河边的城市。哈谢克小说第三卷里，帅克所在的先遣营在这里下了火车，徒步开往前线。城里的主街上有一尊坐在长椅上的帅克铜像", note_en: "The town on the San where, in Book III of Hašek's novel, Švejk's march battalion leaves the train and sets out on foot towards the front. A bronze Švejk sits on a bench in the main street", coord_checked: "Sanok (Polish Wikipedia, article coordinates) — https://pl.wikipedia.org/wiki/Sanok, 2026-11-22", photo: {"file": "images/places/pl-sanok.jpg", "width": 800, "height": 600, "author": "Gorofil", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File%3ASanok._%C5%81aweczka_Szwejka.jpg", "alt_en": "The Švejk bench in Sanok", "alt_zh": "萨诺克的帅克长椅"} }
